const icon=(n)=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.55" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[n]||paths.bag}</svg>`;
const L = window.MoneygoLedger;
const S = window.MoneygoScenario;
const B = window.MoneygoBookkeepingUI;
const I = window.MoneygoImporter;
const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money = cents => `${cents < 0 ? '−' : ''}¥${Math.floor(Math.abs(cents) / 100).toLocaleString('zh-CN')}.${String(Math.abs(cents) % 100).padStart(2,'0')}`;
const amountText = cents => `${cents < 0 ? '-' : ''}${Math.floor(Math.abs(cents) / 100)}.${String(Math.abs(cents) % 100).padStart(2,'0')}`;
const today = () => { const d = new Date(); return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`; };
const $ = selector => document.querySelector(selector);
const ROLLBACK_KEY = 'moneygo.ledger.beforeRestore.v1';
let storage = null, startupError = '', savedRaw = null;
try { storage = window.localStorage; savedRaw = storage.getItem(L.STORAGE_KEY); } catch (_) { startupError = '浏览器不允许本地存储。请允许此网站保存数据，或使用普通浏览模式后重试。'; }
const loaded = storage ? L.load(storage) : {state:L.createEmpty(),error:startupError};
let state = loaded.state || L.createEmpty(), blocked = loaded.error || startupError || '', page = 'report', month = today().slice(0,7);
let filters = {q:'',type:'all',account:'all',category:'all'}, stale = false, toastTimer, lastFocus, modalToken = 0;
const names = {income:'收入',expense:'支出',transfer:'转账'};
const nav = [['report','grid','收支概览'],['ledger','list','交易明细'],['bookkeeping','check','账务核对'],['import','upload','账单导入'],['sandbox','spark','消费沙盘'],['manage','wallet','账户分类'],['backup','shield','数据备份']];
const financeCache = new WeakMap();
function finance(selectedMonth) {let cache=financeCache.get(state);if(!cache){cache=new Map();financeCache.set(state,cache);}const key=selectedMonth||'*';if(!cache.has(key))cache.set(key,L.financialView(state,selectedMonth));return cache.get(key);}
function expenseValue(t) {return finance().impacts[t.id]?.personalExpenseCents||0;}
function incomeValue(t) {return finance().impacts[t.id]?.ordinaryIncomeCents||0;}
function bookkeepingContext(){return {getState:()=>state,engine:window.MoneygoRelations,ledger:L,esc,money,amountText,accountName,categoryName,today,modal,closeModal,error,change,render,$,cancel,options,selected};}
const accountName = id => state.accounts.find(a => a.id === id)?.name || '未知账户';
const categoryName = id => state.categories.find(c => c.id === id)?.name || '';
const monthRows = () => state.transactions.filter(t => t.date.slice(0,7) === month);
const selected = (a,b) => a === b ? 'selected' : '';
const options = (rows,value) => rows.map(r => `<option value="${esc(r.id)}" ${selected(value,r.id)}>${esc(r.name)}</option>`).join('');
function toast(message) { const el=$('#toast'); el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),5000); }
function error(message) { const el=$('#form-error'); if(el){el.textContent=message;el.hidden=false;el.focus();}else toast(message); }
function persist(next,{restore=false}={}) {
  if(!storage) throw Error('本地存储不可用，未保存。');
  if(blocked && !restore) throw Error('原有数据无法读取。请先到「数据备份」导出原始数据，再恢复有效备份。');
  if(stale || storage.getItem(L.STORAGE_KEY)!==savedRaw) { stale=true; throw Error('另一个页面已修改账本。为避免覆盖，请刷新本页后重试。'); }
  const validated=L.save(storage,next);
  state=validated;savedRaw=JSON.stringify(validated);blocked='';
}
function change(fn,message,options) { try {const next=fn();persist(next,options);closeModal(true);render();$('.heading h1')?.focus();toast(message);return true;}catch(e){error(e.message);return false;} }
function render() {
 const title={bookkeeping:['账务核对','每一笔，都有来处。','核对重复证据，理清退款、应收与账户余额。'],report:['收支概览','每一笔，都心中有数。','从今天开始，留住生活里的每一笔收支。'],ledger:['交易明细','认真记下，自在生活。','收入、支出和转账，都能随时核对。'],import:['账单导入','先核对，再记进账本。','选择本地 CSV / TSV，明确来源和列映射，逐笔确认。'],manage:['账户与分类','给每笔钱，找个好位置。','设置期初余额，让账本更贴近实际。'],sandbox:['消费沙盘','给未来的消费，做个预演。','真实历史作参考，新的打算先试一试。'],backup:['数据与备份','记下的生活，好好留存。','本地保存，也请给账本多一份备份。']}[page];
 $('#app').innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><span class="brandmark">${icon('repeat')}</span>moneygo<span class="dot">.</span></div><div class="workspace">MY MONEY, MY WAY</div><nav class="nav" aria-label="主导航">${nav.map(([p,i,t])=>`<button data-page="${p}" class="${page===p?'active':''}" ${page===p?'aria-current="page"':''}>${icon(i)}${t}</button>`).join('')}</nav><div class="side-bottom"><div class="side-note">${icon('shield')}只在这个浏览器保存<br>不上传账单，不自动同步。</div><div class="person"><div class="avatar">M</div><div>我的个人账本<small>本地账本 · 人民币</small></div></div></div></aside><main class="main" id="main-content"><header class="topbar"><div class="crumb">个人账本 ${icon('chevron')} <span>${title[0]}</span></div><div class="brand mobile-brand"><span class="brandmark">${icon('repeat')}</span>moneygo<span class="dot">.</span></div><div class="top-right"><span class="local-label">${blocked||stale?'保存需处理':'本地保存'}</span><button class="iconbutton" data-action="method" aria-label="查看记账口径">${icon('info')}</button></div></header><section class="heading"><div><div class="eyebrow">A LITTLE CLARITY, EVERY DAY</div><h1 tabindex="-1">${title[1]}</h1><p class="subtitle">${title[2]}</p></div><div class="actions">${['report','ledger'].includes(page)?`<label class="sr-only" for="month">选择月份</label><input type="month" class="month-select" id="month" value="${month}" min="0001-01" max="9999-12">`:''}<button class="btn primary" data-action="new" ${blocked?'disabled':''}>${icon('plus')}记一笔</button></div></section>${blocked?`<div class="notice warning" role="alert"><span>${esc(blocked)} 原有存储不会被自动覆盖。<button class="text-link" data-page="backup">前往数据恢复</button></span></div>`:stale?'<div class="notice warning" role="alert">其他页面已更新账本。请刷新本页后再保存，避免覆盖。</div>':''}${page==='bookkeeping'?B.render(bookkeepingContext()):page==='report'?report():page==='ledger'?ledger():page==='manage'?manage():page==='sandbox'?sandbox():page==='import'?importPage():backupPage()}<footer class="page-foot"><span>本地版本 v0.5.0 · 数据保存在当前浏览器，清理网站数据可能丢失账本。请定期导出备份。</span><button data-action="demo">体验虚构样例</button></footer></main></div>`;
 if(page==='import')bindImportPage();
 B.bind(bookkeepingContext());
}
function report() {
 const s=L.summary(state,month),bal=L.balances(state),rows=monthRows();
 const cats=state.categories.filter(c=>c.type==='expense').map(c=>({...c,total:rows.filter(t=>t.type==='expense'&&t.categoryId===c.id).reduce((n,t)=>n+expenseValue(t),0)})).filter(c=>c.total).sort((a,b)=>b.total-a.total);
 const colors=['#6e8461','#e99a72','#d6bb88','#a6b59c','#a5b3bc','#c3b0c6'];let acc=0;
 const gradient=cats.map((c,i)=>{const from=acc;acc+=c.total/s.expenseCents*100;return `${colors[i%colors.length]} ${from}% ${acc}%`;}).join(',');
 return `${state.transactions.length===0?`<section class="welcome card"><div><span class="tiny-label">从空白开始</span><h2>这是你的账本，还没有交易。</h2><p>先设置账户期初余额，再记下第一笔。也可以进入独立的样例演示。</p></div><div class="actions"><button class="btn" data-page="manage">设置账户</button><button class="btn primary" data-action="new">记下第一笔 ${icon('arrow')}</button></div></section>`:''}<section class="stats"><article class="stat hero"><div class="stat-label">${state.bookkeeping?'本月个人消费':'本月支出'} ${icon('bag')}</div><div class="big-number">${money(s.expenseCents)}</div><div class="stat-foot">${rows.filter(t=>t.type==='expense'&&!finance().impacts[t.id]?.excluded).length} 笔支出 · ${state.bookkeeping?'已扣关联退款和应收份额':'转账不计消费'}</div></article><article class="stat"><div class="stat-label">${state.bookkeeping?'本月普通收入':'本月收入'}</div><div class="big-number secondary income">${money(s.incomeCents)}</div><div class="stat-foot">${rows.filter(t=>t.type==='income').length} 笔收入</div></article><article class="stat"><div class="stat-label">${state.bookkeeping?'个人收支差额':'本月结余'}</div><div class="big-number secondary">${money(s.netCents)}</div><div class="stat-foot">${state.bookkeeping?'普通收入 − 个人消费，不等于现金变化':'收入 − 支出，不含期初余额'}</div></article></section>${state.bookkeeping?B.reportSummary(bookkeepingContext(),month):''}<section class="content-grid"><article class="card"><div class="card-head"><div><h2>钱都花在哪儿</h2><p>按支出分类，看看消费的重心</p></div><span class="tiny-label">${month}</span></div>${cats.length?`<div class="category-area"><div class="donut" style="background:conic-gradient(${gradient})" role="img" aria-label="本月支出分类占比"><div class="donut-center"><span>最大支出</span><strong>${Math.round(cats[0].total/s.expenseCents*100)}%</strong><span class="donut-label">${esc(cats[0].name)}</span></div></div><div class="legend">${cats.map((c,i)=>`<button class="legend-row" data-category="${esc(c.id)}"><span class="legend-name"><i class="swatch" style="background:${colors[i%colors.length]}"></i>${esc(c.name)}</span><span class="legend-value">${money(c.total)}</span></button>`).join('')}</div></div>`:'<div class="empty"><span class="empty-icon">'+icon('bag')+'</span><h3>这个月还没有可统计的消费</h3><p>记下第一笔后，这里会慢慢丰富起来。</p></div>'}</article><article class="card"><div class="card-head"><div><h2>账户余额</h2><p>期初余额 + 全部已记收支与转账</p></div><button class="text-link" data-page="manage">管理 ${icon('arrow')}</button></div>${state.accounts.map(a=>`<div class="account-line"><span>${icon('wallet')}${esc(a.name)}</span><strong>${money(bal[a.id])}</strong></div>`).join('')}<div class="account-total"><span>全部账户合计</span><strong>${money(finance().balanceTotalCents)}</strong></div><p class="history-note">账本余额包含全部日期的记录；未记入的交易不会体现，不代表银行实时余额。</p></article></section><article class="card"><div class="card-head"><h2>最近的几笔</h2><button class="text-link" data-page="ledger">全部交易 ${icon('arrow')}</button></div>${rows.length?rows.slice().sort((a,b)=>b.date.localeCompare(a.date)).slice(0,5).map(t=>txRow(t)).join(''):'<div class="empty compact">这个月还没有记录。选择其他月份，或记一笔新的收支。</div>'}</article>`;
}
function txRow(t,deleted=false) { return `<button class="transaction-row" ${deleted?`data-undo="${esc(t.id)}"`:`data-tx="${esc(t.id)}"`}><span class="merchant-icon">${icon(t.type==='transfer'?'repeat':t.type==='income'?'download':'bag')}</span><span><span class="tx-name">${esc(t.note||categoryName(t.categoryId)||'账户转账')}</span><span class="tx-meta">${t.date} · ${esc(accountName(t.accountId))}${t.type==='transfer'?` → ${esc(accountName(t.toAccountId))}`:` · ${esc(categoryName(t.categoryId))}`}</span></span><span class="tx-amount ${t.type==='income'?'income':''}">${t.type==='income'?'+':t.type==='expense'?'−':''}${money(t.amountCents)}<small>${deleted?'点击恢复':finance().impacts[t.id]?.excluded?'重复证据 · 未重复计账':names[t.type]}</small></span></button>`; }
function ledger() {
 const rows=monthRows().filter(t=>(filters.type==='all'||t.type===filters.type)&&(filters.account==='all'||t.accountId===filters.account||t.toAccountId===filters.account)&&(filters.category==='all'||t.categoryId===filters.category)&&(`${t.note} ${accountName(t.accountId)} ${t.toAccountId?accountName(t.toAccountId):''} ${categoryName(t.categoryId)}`.toLowerCase().includes(filters.q.toLowerCase()))).sort((a,b)=>b.date.localeCompare(a.date));
 return `<article class="card"><div class="card-head"><h2>每一笔收支</h2><span class="tiny-label">${rows.length} 笔</span></div><div class="filters"><label class="search">${icon('search')}<input id="search" maxlength="500" value="${esc(filters.q)}" placeholder="搜索备注、账户或分类" aria-label="搜索交易"></label><select class="month-select" id="filter-type" aria-label="筛选类型"><option value="all">全部类型</option>${Object.entries(names).map(([k,v])=>`<option value="${k}" ${selected(filters.type,k)}>${v}</option>`).join('')}</select><select class="month-select" id="filter-account" aria-label="筛选账户"><option value="all">全部账户</option>${options(state.accounts,filters.account)}</select><select class="month-select" id="filter-category" aria-label="筛选分类"><option value="all">全部分类</option>${options(state.categories,filters.category)}</select></div><div class="ledger-summary"><span>${state.bookkeeping?'个人消费':'支出'} ${money(rows.filter(t=>t.type==='expense').reduce((n,t)=>n+expenseValue(t),0))}</span><span>${state.bookkeeping?'普通收入':'收入'} ${money(rows.filter(t=>t.type==='income').reduce((n,t)=>n+incomeValue(t),0))}</span><button class="text-link" data-action="clear-filters">清除筛选</button></div>${rows.length?rows.map(t=>txRow(t)).join(''):'<div class="empty">没有符合条件的交易。<br>试试清除筛选，或选择其他月份。</div>'}</article><p class="history-note">逐行金额保留原始资金流水，汇总显示个人消费／普通收入；关联重复证据不重复计数。点击交易查看原金额、退款和应收分解。有关联的财务字段须先撤销关联再编辑，删除后可到回收区恢复。</p>`;
}
function manage() {
 const bal=L.balances(state);
 return `<article class="card section-space"><div class="card-head"><div><h2>我的账户</h2><p>账户不连接银行，余额由你记录的交易计算</p></div><button class="btn" data-action="add-account">${icon('plus')}新增账户</button></div><div class="account-grid">${state.accounts.map(a=>`<section class="account-tile"><div class="account-tile-head">${icon('wallet')}<h3>${esc(a.name)}</h3><button class="text-link" data-account="${esc(a.id)}">编辑</button></div><strong>${money(bal[a.id])}</strong><p>期初余额 ${money(a.openingBalanceCents)}</p></section>`).join('')}</div></article><article class="card"><div class="card-head"><h2>收支分类</h2><button class="btn" data-action="add-category">${icon('plus')}新增分类</button></div>${['expense','income'].map(type=>`<section class="category-section"><h3>${names[type]}分类</h3><div class="category-chips">${state.categories.filter(c=>c.type===type).map(c=>`<button class="category-chip" data-edit-category="${esc(c.id)}">${esc(c.name)} ${icon('chevron')}</button>`).join('')||'<span class="muted">暂无分类，请新增。</span>'}</div></section>`).join('')}<p class="history-note">有交易引用的账户与分类不能删除，包含已删除但可恢复的交易。修改名称会同步显示于历史记录。</p></article>`;
}
function backupPage() {
 let hasRollback=false;try{hasRollback=!!storage?.getItem(ROLLBACK_KEY);}catch(_){}
 return `<div class="notice">${icon('shield')}<span>账本只保存在当前设备的这个浏览器中，不会上传或跨设备同步。清理网站数据、使用无痕模式或更换网址可能使数据不可用。备份文件包含完整财务记录，请妥善保管。</span></div><div class="backup-grid"><article class="card"><div class="card-head"><h2>导出备份</h2>${icon('download')}</div><p class="body-copy">保存账户、分类、全部交易、已删除交易、消费沙盘设置，以及导入模板、来源证据、批次、待核对记录和覆盖确认，为 JSON 文件。原始 CSV 文件内容不进入备份。跨设备时，可在另一个浏览器中恢复此文件。</p><button class="btn" data-action="verify-backup">验证备份（不替换账本）</button><button class="btn primary" data-action="export" ${blocked?'disabled':''}>导出账本 JSON</button>${blocked?'<button class="btn" data-action="export-raw">导出无法读取的原始数据</button>':''}</article><article class="card"><div class="card-head"><h2>从备份恢复</h2>${icon('upload')}</div><p class="body-copy">仅接受 moneygo JSON 备份。先校验并显示预览，确认后替换当前账本。恢复前会在浏览器保留一份原账本供撤销。</p><button class="btn" data-action="restore">选择 JSON 备份</button>${hasRollback?'<button class="text-link rollback-link" data-action="rollback">撤销上次恢复</button>':''}</article></div><article class="card section-space"><div class="card-head"><h2>已删除交易</h2><span class="tiny-label">${state.trash.length} 笔</span></div><p class="body-copy">这些交易不计入收支和余额，点击可恢复。不会自动永久清除。</p>${state.trash.length?state.trash.slice().reverse().map(e=>txRow(e.transaction,true)).join(''):'<div class="empty compact">没有已删除的交易。</div>'}</article><article class="card"><div class="card-head"><h2>账单导入</h2><span class="tiny-label">本地 CSV / TSV</span></div><p class="body-copy">导入前检查格式、设置列映射并逐笔核对。仅保存已映射的必要字段与来源证据，原始文件留在你的设备。不同平台的导出格式需要你核对，不承诺官方兼容。</p><button class="btn" data-page="import">导入和查看历史 ${icon('arrow')}</button></article>`;
}
function modal(title,body,buttons='',ready) {
 modalToken++;if(!$('.modal'))lastFocus=document.activeElement;
 $('#modal-root').innerHTML=`<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-head"><h2 id="modal-title">${esc(title)}</h2><button data-close aria-label="关闭">${icon('close')}</button></div>${body}<p id="form-error" class="form-error" role="alert" tabindex="-1" hidden></p>${buttons?`<div class="modal-bottom">${buttons}</div>`:''}</section></div>`;
 document.body.style.overflow='hidden';$('#app').inert=true;$('.modal [data-close]')?.focus();ready?.();
}
function closeModal(force=false) {
 if(!force && $('#entry-form')?.dataset.dirty==='true' && !window.confirm('放弃未保存的修改？'))return;
 modalToken++;$('#modal-root').innerHTML='';document.body.style.overflow='';$('#app').inert=false;if(lastFocus?.isConnected)lastFocus.focus();else $('.heading h1')?.focus();
}
const cancel='<button class="btn" type="button" data-close>取消</button>';
function entry(id) {
 const t=state.transactions.find(t=>t.id===id);const data=t||{type:'expense',date:today(),accountId:state.accounts[0]?.id,note:''};
 modal(t?'编辑交易':'记一笔',`<form id="entry-form"><div class="type-switch" role="group" aria-label="交易类型">${Object.entries(names).map(([k,v])=>`<label><input type="radio" name="type" value="${k}" ${data.type===k?'checked':''}><span>${v}</span></label>`).join('')}</div><div class="form-grid"><label class="field amount-field full">金额（人民币元）<input id="amount" name="amount" type="text" inputmode="decimal" maxlength="14" autocomplete="off" placeholder="0.00" value="${t?amountText(t.amountCents):''}" required></label><label class="field">日期<input name="date" type="date" min="0001-01-01" max="9999-12-31" value="${data.date}" required></label><label class="field"><span id="account-label">账户</span><select name="accountId" required>${options(state.accounts,data.accountId)}</select></label><label class="field full" id="category-field">分类<select name="categoryId" required></select></label><label class="field full" id="destination-field" hidden>转入账户<select name="toAccountId">${options(state.accounts,data.toAccountId||state.accounts.find(a=>a.id!==data.accountId)?.id)}</select></label><label class="field full">备注（可选）<textarea name="note" rows="3" maxlength="500" placeholder="这笔钱用在了哪里？">${esc(data.note)}</textarea></label></div><p class="form-hint" id="entry-hint"></p>${t?B.transactionDetails(bookkeepingContext(),t.id):''}<div class="modal-bottom">${t?'<button class="btn danger" type="button" id="delete-transaction">删除</button>':''}${cancel}<button class="btn primary" type="submit">保存${t?'修改':''}</button></div></form>`,'',()=>{
  const form=$('#entry-form');
  function typeChanged(){const type=form.elements.type.value,transfer=type==='transfer';$('#category-field').hidden=transfer;$('#destination-field').hidden=!transfer;form.elements.categoryId.required=!transfer;form.elements.toAccountId.required=transfer;form.elements.categoryId.innerHTML=options(state.categories.filter(c=>c.type===type),data.categoryId);$('#account-label').textContent=transfer?'转出账户':'账户';$('#entry-hint').textContent=transfer?'转账会同时减少转出账户余额、增加转入账户余额，不计收入或支出。':'金额大于 0，最多两位小数。账本按交易日期统计。';}
  typeChanged();form.elements.type.forEach(r=>r.onchange=typeChanged);
  form.addEventListener('input',()=>form.dataset.dirty='true');form.addEventListener('change',()=>form.dataset.dirty='true');
  form.onsubmit=e=>{e.preventDefault();try{const values=new FormData(form),type=values.get('type');const input={type,date:values.get('date'),amountCents:L.parseAmount(values.get('amount')),accountId:values.get('accountId'),note:values.get('note')};if(type==='transfer')input.toAccountId=values.get('toAccountId');else input.categoryId=values.get('categoryId');const next=L.putTransaction(state,input,t?.id);persist(next);month=input.date.slice(0,7);closeModal(true);render();toast(t?'交易已更新':'已保存到当前浏览器');}catch(e){error(e.message);}};
  if(t)$('#delete-transaction').onclick=()=>confirmDelete(t);
  $('#amount').focus();
 });
}
function confirmDelete(t) {modal('删除这笔交易？',`<p>${esc(t.note||names[t.type])} · ${t.date} · ${money(t.amountCents)}</p><p>删除后收支和账户余额会重算。你可以随时在「数据备份 → 已删除交易」恢复。</p>`,`${cancel}<button class="btn danger" id="confirm-delete">确认删除</button>`,()=>$('#confirm-delete').onclick=()=>change(()=>L.deleteTransaction(state,t.id),'已删除，可到「数据备份」恢复'));}
function editAccount(id) {
 const a=state.accounts.find(a=>a.id===id);
 modal(a?'编辑账户':'新增账户',`<form id="entry-form"><div class="form-grid"><label class="field full">账户名称<input name="name" value="${esc(a?.name||'')}" maxlength="80" placeholder="例如：工资卡" required></label><label class="field full">期初余额（人民币元）<input name="opening" type="text" inputmode="decimal" value="${a?amountText(a.openingBalanceCents):'0.00'}" maxlength="15" required></label></div><p class="form-hint">记第一笔交易前的账户余额，可为负数。不是收入；修改期初余额会调整当前账本余额。</p><div class="modal-bottom">${a?'<button class="btn danger" type="button" id="remove-account">删除账户</button>':''}${cancel}<button class="btn primary" type="submit">保存账户</button></div></form>`,'',()=>{
  const f=$('#entry-form');f.addEventListener('input',()=>f.dataset.dirty='true');f.onsubmit=e=>{e.preventDefault();try{const input={name:f.elements.name.value,openingBalanceCents:L.parseAmount(f.elements.opening.value,{allowNegative:true,allowZero:true})};const next=L.putAccount(state,input,a?.id);if(a&&input.openingBalanceCents!==a.openingBalanceCents){modal('调整期初余额？',`<p>${esc(input.name)} 的期初余额将从 ${money(a.openingBalanceCents)} 改为 ${money(input.openingBalanceCents)}。账户余额同步调整，历史交易保持不变。</p>`,`${cancel}<button class="btn primary" id="confirm-opening">确认调整</button>`,()=>$('#confirm-opening').onclick=()=>change(()=>next,'账户已更新'));}else change(()=>next,'账户已保存');}catch(e){error(e.message);}};
  if(a)$('#remove-account').onclick=()=>modal('删除账户？',`<p>将删除「${esc(a.name)}」。其期初余额 ${money(a.openingBalanceCents)} 也将从账户合计中移除。有交易引用的账户无法删除。</p>`,`${cancel}<button class="btn danger" id="confirm-remove">确认删除账户</button>`,()=>$('#confirm-remove').onclick=()=>change(()=>L.removeAccount(state,a.id),'账户已删除'));
 });
}
function editCategory(id) {
 const c=state.categories.find(c=>c.id===id);
 modal(c?'编辑分类':'新增分类',`<form id="entry-form"><div class="form-grid"><label class="field full">分类名称<input name="name" maxlength="80" value="${esc(c?.name||'')}" required></label><label class="field full">类型<select name="type" ${c?'disabled':''}><option value="expense">支出</option><option value="income" ${c?.type==='income'?'selected':''}>收入</option></select></label></div><p class="form-hint">已创建分类的收支类型不能更改，避免改变历史交易的含义。</p><div class="modal-bottom">${c?'<button class="btn danger" type="button" id="remove-category">删除分类</button>':''}${cancel}<button class="btn primary" type="submit">保存分类</button></div></form>`,'',()=>{
  const f=$('#entry-form');f.addEventListener('input',()=>f.dataset.dirty='true');f.onsubmit=e=>{e.preventDefault();change(()=>L.putCategory(state,{name:f.elements.name.value,type:c?.type||f.elements.type.value},c?.id),'分类已保存');};
  if(c)$('#remove-category').onclick=()=>modal('删除分类？',`<p>将删除「${esc(c.name)}」。有交易引用的分类无法删除，包括已删除的可恢复交易。</p>`,`${cancel}<button class="btn danger" id="confirm-remove">确认删除分类</button>`,()=>$('#confirm-remove').onclick=()=>change(()=>L.removeCategory(state,c.id),'分类已删除'));
 });
}
function download(text,filename) { const blob=new Blob([text],{type:'application/json;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000); }
function showRestore() {
 modal('选择账本备份',`<p>选择 moneygo 导出的 JSON 文件（最多 32 MB）。文件只在浏览器内读取，不会上传。</p><label class="field restore-file">JSON 备份文件<input type="file" accept=".json,application/json" id="restore-file"></label><div id="restore-preview"></div>`,cancel,()=>{
 const token=modalToken;let readNumber=0;$('#restore-file').onchange=async e=>{const read=++readNumber;$('#restore-preview').innerHTML='';$('#form-error').hidden=true;const file=e.target.files[0];if(!file)return;try{if(file.size>32*1024*1024)throw Error('文件超过 32 MB，请选择有效备份。');const text=await file.text();if(token!==modalToken||read!==readNumber)return;const next=L.parseBackup(text);restorePreview(next);}catch(e){if(token===modalToken&&read===readNumber){$('#restore-preview').innerHTML='';error(e.message);}}};
 });
}
function restorePreview(next) {
 const dates=next.transactions.map(t=>t.date).sort();
 $('#restore-preview').innerHTML=`<div class="restore-summary"><h3>备份已通过校验</h3><p>${next.accounts.length} 个账户 · ${next.categories.length} 个分类<br>${next.transactions.length} 笔交易 · ${next.trash.length} 笔已删除交易<br>${next.simulation?next.simulation.scenarios.length+' 个模拟方案':'无模拟方案（旧版备份兼容）'}<br>${next.imports?next.imports.batches.length+' 个导入批次 · '+next.imports.quarantine.length+' 条待核对记录':'无导入记录（旧版备份兼容）'}<br>${next.bookkeeping?next.bookkeeping.links.length+' 组证据关联 · '+next.bookkeeping.refunds.length+' 笔退款分配 · '+next.bookkeeping.claims.length+' 笔应收':'无账务关系（旧版备份兼容）'}<br>${dates.length?`${dates[0]} 至 ${dates[dates.length-1]}`:'空账本'} · 人民币</p></div><p>当前账本：${state.transactions.length} 笔交易。恢复会完整替换账本、沙盘及导入记录，不会合并。旧版备份不含的设置与导入记录将被清除。原账本将保留一份供撤销下次恢复前使用。</p><label class="confirm-check"><input type="checkbox" id="restore-consent">我确认用这份备份替换当前账本</label><button class="btn primary" id="confirm-restore" disabled>确认替换并恢复</button>`;
 $('#restore-consent').onchange=e=>$('#confirm-restore').disabled=!e.target.checked;
 $('#confirm-restore').onclick=()=>{try{if(!$('#restore-consent').checked)return;if(!storage)throw Error('本地存储不可用，不能恢复。');if(stale||storage.getItem(L.STORAGE_KEY)!==savedRaw)throw Error('其他页面已修改账本，请刷新后重试。');const original=savedRaw ?? JSON.stringify(state),previousRollback=storage.getItem(ROLLBACK_KEY);storage.setItem(ROLLBACK_KEY,original);try{if(storage.getItem(ROLLBACK_KEY)!==original)throw Error('无法保留原账本，恢复已取消。');persist(next,{restore:true});}catch(saveError){try{if(previousRollback===null)storage.removeItem(ROLLBACK_KEY);else storage.setItem(ROLLBACK_KEY,previousRollback);}catch(_){throw Error(saveError.message+' 原先的撤销副本无法还原，请立即导出当前账本。');}throw saveError;}closeModal(true);render();toast('恢复成功，原账本可通过「撤销上次恢复」找回。');}catch(e){error(`恢复未完成：${e.message}`);}};
}
function rollback() {try{const raw=storage?.getItem(ROLLBACK_KEY);if(!raw)throw Error('没有可撤销的恢复。');const next=L.validateState(JSON.parse(raw));modal('撤销上次恢复？',`<p>将用恢复前保留的 ${next.transactions.length} 笔交易替换当前账本。上次恢复之后新增或修改的内容会被替换，请先导出当前备份。</p>`,`${cancel}<button class="btn" id="export-current">导出当前备份</button><button class="btn primary" id="confirm-rollback">确认撤销恢复</button>`,()=>{$('#export-current').onclick=()=>download(L.backup(state),`moneygo-${today()}.json`);$('#confirm-rollback').onclick=()=>change(()=>next,'已恢复到上次恢复之前的账本',{restore:true});});}catch(e){modal('无法自动撤销',`<p>保留的原始数据无法通过校验。可以先下载保留的数据进行检查，当前账本不会改变。</p>`,`${cancel}<button class="btn" id="download-original">下载保留的原始数据</button>`,()=>$('#download-original').onclick=()=>{try{const raw=storage?.getItem(ROLLBACK_KEY);if(raw)download(raw,`moneygo-recovery-${today()}.json`);}catch(e){error(e.message);}});}}
function demo() {modal('进入独立的样例演示',`<p>演示使用虚构交易，包含模拟账单导入、重复关联和退款确认。不会改变你的真实账本。演示中的修改刷新后重置。</p>`,`${cancel}<a class="btn primary" href="demo.html">进入虚构样例</a>`);}
function method(){modal('怎样计算这本账',`<div class="accounting-steps"><div class="accounting-step"><strong>收入、支出、结余</strong>按交易日期的年月统计；启用账务关联后，个人消费扣除已关联退款与应收份额，普通收入扣除退款及回款。现金按实际到账／付出日期单列，后续退款可重算原购买月。所有金额以整数分保存。</div><div class="accounting-step"><strong>账户余额</strong>期初余额 + 全部收入 − 全部支出 + 转入 − 转出，包含全部日期。期初余额不计作收入。</div><div class="accounting-step"><strong>转账不算消费</strong>同一笔转账同时影响两个不同账户，不计收入、支出或结余。转账手续费可另记支出。</div><div class="accounting-step"><strong>本地账本</strong>支持人民币手动收支、账户转账和用户映射的本地 CSV / TSV 收支导入。来源标识用于区分数据，目标账户单独指定；候选重复不会自动合并。支持人工确认多份证据、已到账退款和应收回款；个人消费与实际现金流分开展示。暂不提供官方账单格式兼容、自动同步或信用卡专用账期。</div></div>`, '<button class="btn primary" data-close>知道了</button>');}
